export const Route = createFileRoute("/_authenticated/gestor/escala")({
  validateSearch:(search:Record<string,unknown>)=>({reforcoData:typeof search.reforcoData==="string"?search.reforcoData:undefined,reforcoUnidade:(search.reforcoUnidade==="Botafogo"||search.reforcoUnidade==="Ipanema"?search.reforcoUnidade:undefined) as "Botafogo"|"Ipanema"|undefined}),
  beforeLoad: () => requireGestor(),
  head: () => ({ meta: [
    { title: "Escala de Funcionários — INJOY" },
    { name: "description", content: "Geração, validação e publicação das escalas mensais do INJOY." },
    { property: "og:title", content: "Escala de Funcionários — INJOY" },
    { property: "og:description", content: "Geração, validação e publicação das escalas mensais do INJOY." },
    { property: "og:type", content: "website" },
    { name: "twitter:card", content: "summary" },
  ] }),
  component: EscalaPage,
});

type UnitFilter="Botafogo"|"Ipanema"|"Ambas";
type ViewMode="calendar"|"grid";
const MONTHS=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
const SECTION_LABEL:Record<EscalaSetor,string>={manutencao:"Manutenção",recepcao:"Recepção",camareiras:"Camareiras"};
const STATUS_LABEL:Record<EscalaDia["status"],string>={trabalho:"Trabalho",folga:"Folga",falta:"Falta",atestado:"Atestado",ferias:"Férias",extra:"Extra"};
const STATUS_CODE:Record<EscalaDia["status"],string>={trabalho:"T",folga:"F",falta:"FT",atestado:"AT",ferias:"FE",extra:"T"};
// Valores pagos a freelancers ficam escondidos no calendário (tela pode ser mostrada/printada para a equipe).
const VALORES_KEY="escala-mostrar-valores"; const valoresListeners=new Set<()=>void>();
const lerValores=()=>{try{return localStorage.getItem(VALORES_KEY)==="1";}catch{return false;}};
const gravarValores=(v:boolean)=>{try{localStorage.setItem(VALORES_KEY,v?"1":"0");}catch{/* sem storage: só nesta sessão */}valoresListeners.forEach(l=>l());};
function useMostrarValores(){const v=useSyncExternalStore(cb=>{valoresListeners.add(cb);return()=>valoresListeners.delete(cb);},lerValores,()=>false);return [v,gravarValores] as const;}
const money=(n:number)=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(n);
const activePattern=(c:EscalaColaborador)=>c.escala_padroes?.find(p=>!p.vigente_ate)??null;
const appliesTo=(c:EscalaColaborador,u:UnitFilter)=>u==="Ambas"||c.unidade==="Ambas"||c.unidade===u;
const competence=(y:number,m:number)=>`${y}-${String(m+1).padStart(2,"0")}-01`;

function exportSchedulePdf(year:number,month:number,unit:UnitFilter,sector:EscalaSetor,people:EscalaColaborador[],days:EscalaDia[],holidays:{data:string;nome:string}[]){
  const doc=new jsPDF({orientation:"landscape",unit:"mm",format:"a4"});
  const units:("Botafogo"|"Ipanema")[]=unit==="Ambas"?["Botafogo","Ipanema"]:[unit];
  const bounds=monthBounds(year,month);const dates=civilRange(bounds.start,bounds.end);const holidayMap=new Map(holidays.map(h=>[h.data,h.nome]));
  units.forEach((current,index)=>{if(index)doc.addPage("a4","landscape");const members=people.filter(p=>p.ativo&&p.setor===sector&&(p.unidade===current||p.unidade==="Ambas"));doc.setFontSize(15);doc.text(`Escala INJOY · ${current} · ${SECTION_LABEL[sector]} · ${MONTHS[month]}/${year}`,12,13);doc.setFontSize(7);doc.text("T = trabalho · F = folga · FT = falta · AT = atestado · FE = férias · * = feriado",12,18);autoTable(doc,{startY:22,head:[["Pessoa",...dates.map(d=>`${Number(d.slice(-2))}${holidayMap.has(d)?"*":""}`)]],body:members.map(p=>[p.nome,...dates.map(date=>{const row=days.find(d=>d.colaborador_id===p.id&&d.unidade===current&&d.data===date);return row?STATUS_CODE[row.status]:"·";})]),styles:{fontSize:6,cellPadding:1,halign:"center"},headStyles:{fillColor:[30,64,175]},columnStyles:{0:{cellWidth:36,halign:"left"}},margin:{left:7,right:7}});const finalY=(doc as jsPDF&{lastAutoTable?:{finalY:number}}).lastAutoTable?.finalY??160;doc.setFontSize(8);doc.text(`Feriados: ${holidays.filter(h=>h.data>=bounds.start&&h.data<=bounds.end).map(h=>`${h.data.slice(-2)} — ${h.nome}`).join("; ")||"Nenhum"}`,12,Math.min(finalY+8,185));doc.text("Assinatura do gestor: __________________________________________",12,Math.min(finalY+18,195));doc.text(`Data: ${todaySP().split("-").reverse().join("/")}`,220,Math.min(finalY+18,195));});doc.save(`escala-${year}-${String(month+1).padStart(2,"0")}-${sector}.pdf`);
}

function EscalaPage(){
  const search=Route.useSearch();
  const now=todaySP(); const [year,setYear]=useState(Number(now.slice(0,4))); const [month,setMonth]=useState(Number(now.slice(5,7))-1);
  const [unit,setUnit]=useState<UnitFilter>(search.reforcoUnidade??"Botafogo"); const [sector,setSector]=useState<EscalaSetor>(search.reforcoData?"camareiras":"recepcao"); const [view,setView]=useState<ViewMode>("calendar"); const [teamOpen,setTeamOpen]=useState(false); const [vaOpen,setVaOpen]=useState(false);
  const bounds=monthBounds(year,month); const queryStart=addCivilDays(bounds.start,-7); const queryEnd=addCivilDays(bounds.end,7);
  const peopleQuery=useEscalaColaboradores(); const daysQuery=useEscalaDias(queryStart,queryEnd); const holidaysQuery=useEscalaFeriados(); const monthsQuery=useEscalaMeses(bounds.start);
  const people=peopleQuery.data??[]; const allDays=daysQuery.data??[]; const visibleUnits: ("Botafogo"|"Ipanema")[]=unit==="Ambas"?["Botafogo","Ipanema"]:[unit];
  const sectionPeople=useMemo(()=>people.filter(p=>p.ativo&&p.setor===sector&&appliesTo(p,unit)),[people,sector,unit]);
  const visibleDays=useMemo(()=>allDays.filter(d=>d.setor===sector&&visibleUnits.includes(d.unidade)&&d.data>=bounds.start&&d.data<=bounds.end),[allDays,sector,unit,bounds.start,bounds.end]);
  const months=(monthsQuery.data??[]).filter(m=>m.setor===sector&&visibleUnits.includes(m.unidade));
  const issues=useMemo(()=>buildIssues(people,allDays,holidaysQuery.data??[],sector,visibleUnits).filter(i=>!i.date||(i.date>=bounds.start&&i.date<=bounds.end)),[people,allDays,holidaysQuery.data,sector,unit,bounds.start,bounds.end]);
  const loading=peopleQuery.isLoading||daysQuery.isLoading;
  const vaAlerta=useMemo(()=>{if(vaOpen)return null;const c=lerConfigBeneficios();const l=calcularBeneficios(people,allDays,bounds.start,bounds.end,numBeneficio(c.va),numBeneficio(c.vt));const t=totaisBeneficios(l).total;const sep=numBeneficio(c.separado);const sem=l.filter(x=>x.semEscala).length;return {passou:sep>0&&t>sep,sem};},[people,allDays,bounds.start,bounds.end,vaOpen]);
  const changeMonth=(delta:number)=>{let m=month+delta,y=year;if(m<0){m=11;y--;}if(m>11){m=0;y++;}setMonth(m);setYear(y);};
  return <div className="space-y-5 print:space-y-2">
    <header className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between print:hidden"><div><Badge variant="secondary" className="mb-2 rounded-full"><CalendarDays className="mr-1 h-3 w-3"/>Gestão</Badge><h1 className="text-2xl font-bold sm:text-3xl">Escala de Funcionários</h1><p className="mt-1 text-sm text-muted-foreground">Ciclos contínuos, validação e publicação mensal.</p></div><div className="flex flex-wrap gap-2"><ToggleValores/><Button variant="outline" onClick={()=>setVaOpen(true)}><Wallet className="mr-2 h-4 w-4"/>Vale alimentação e transporte{vaAlerta?.passou&&<span className="ml-2 rounded-full bg-red-600 px-1.5 text-[10px] text-white" title="Total acima do valor separado">acima do separado</span>}{!!vaAlerta?.sem&&<span className="ml-2 rounded-full bg-amber-500 px-1.5 text-[10px] text-white" title="Há fixos sem escala gerada neste mês">{vaAlerta.sem} sem escala</span>}</Button><Button variant="outline" onClick={()=>exportSchedulePdf(year,month,unit,sector,people,allDays,holidaysQuery.data??[])}><FileDown className="mr-2 h-4 w-4"/>Baixar PDF</Button><WhatsApp days={visibleDays} people={sectionPeople} label={`${MONTHS[month]}/${year}`}/><Button variant="outline" onClick={()=>setTeamOpen(true)}><Users className="mr-2 h-4 w-4"/>Equipe da Escala</Button></div></header>
    <Card className="p-4 sm:p-5 print:border-0 print:p-0">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3 print:hidden">
        <div className="flex items-center gap-2"><Button size="icon" variant="outline" onClick={()=>changeMonth(-1)} aria-label="Mês anterior"><ChevronLeft className="h-4 w-4"/></Button><div className="min-w-36 rounded-md border bg-muted/40 px-3 py-2 text-center text-sm font-medium">{MONTHS[month]} / {year}</div><Button size="icon" variant="outline" onClick={()=>changeMonth(1)} aria-label="Próximo mês"><ChevronRight className="h-4 w-4"/></Button></div>
        <div className="flex flex-wrap gap-2"><Select value={unit} onValueChange={v=>setUnit(v as UnitFilter)}><SelectTrigger className="w-36"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="Botafogo">Botafogo</SelectItem><SelectItem value="Ipanema">Ipanema</SelectItem><SelectItem value="Ambas">Ambas</SelectItem></SelectContent></Select><div className="flex rounded-md border p-1"><Button size="sm" variant={view==="calendar"?"secondary":"ghost"} onClick={()=>setView("calendar")}><Grid3X3 className="mr-1 h-4 w-4"/>Calendário</Button><Button size="sm" variant={view==="grid"?"secondary":"ghost"} onClick={()=>setView("grid")}><List className="mr-1 h-4 w-4"/>Por pessoa</Button></div></div>
      </div>
      <Tabs value={sector} onValueChange={v=>setSector(v as EscalaSetor)}><TabsList className="grid w-full grid-cols-3 print:hidden"><TabsTrigger value="manutencao">Manutenção</TabsTrigger><TabsTrigger value="recepcao">Recepção</TabsTrigger><TabsTrigger value="camareiras">Camareiras</TabsTrigger></TabsList>
        <TabsContent value={sector} className="mt-4"><ScheduleWorkspace year={year} month={month} unit={unit} sector={sector} view={view} people={sectionPeople} allPeople={people} days={visibleDays} contextDays={allDays} months={months} issues={issues} holidays={holidaysQuery.data??[]} loading={loading} initialFree={search.reforcoData&&search.reforcoUnidade?{date:search.reforcoData,unit:search.reforcoUnidade}:null}/></TabsContent>
      </Tabs>
    </Card>
    {vaOpen&&<BeneficiosDialog open onClose={()=>setVaOpen(false)} people={people} days={allDays} start={bounds.start} end={bounds.end} label={`${MONTHS[month]}/${year}`}/>}
    <EquipeEscalaDialog open={teamOpen} onOpenChange={setTeamOpen}/><ImportarEquipeLocalPrompt/>
  </div>;
}

function ScheduleWorkspace({year,month,unit,sector,view,people,allPeople,days,contextDays,months,issues,holidays,loading,initialFree}:{year:number;month:number;unit:UnitFilter;sector:EscalaSetor;view:ViewMode;people:EscalaColaborador[];allPeople:EscalaColaborador[];days:EscalaDia[];contextDays:EscalaDia[];months:EscalaMes[];issues:ScheduleIssue[];holidays:{data:string;nome:string}[];loading:boolean;initialFree:{date:string;unit:"Botafogo"|"Ipanema"}|null}){
  const generate=useGerarEscalaMes(); const publish=usePublicarEscalaMes(); const save=useSalvarEscalaDia(); const saveMany=useSalvarEscalaDias(); const modalities=useEscalaModalidades(); const bounds=monthBounds(year,month);
  const [edit,setEdit]=useState<{person:EscalaColaborador;date:string;row?:EscalaDia}|null>(null); const [free,setFree]=useState<{date:string;unit:"Botafogo"|"Ipanema";replaces?:string}|null>(initialFree); const [regenerate,setRegenerate]=useState(false); const [override,setOverride]=useState<{patches:EscalaDiaInput[];errors:ScheduleIssue[]}|null>(null); const [reason,setReason]=useState(""); const [publishOverride,setPublishOverride]=useState<ScheduleIssue[]|null>(null); const [publishReason,setPublishReason]=useState(""); const [coverOpen,setCoverOpen]=useState(false); const [feriasOpen,setFeriasOpen]=useState(false);
  const generatedCount=days.filter(d=>d.origem==="gerado").length; const publication=months.length&&months.every(m=>m.status==="publicada")?"publicada":"rascunho";
  const units:("Botafogo"|"Ipanema")[]=unit==="Ambas"?["Botafogo","Ipanema"]:[unit];
  const doGenerate=async()=>{if(unit==="Ambas")return toast.error("Selecione Botafogo ou Ipanema para gerar; Ambas é uma visão consolidada.");
    const fixos=allPeople.filter(p=>p.ativo&&p.vinculo==="fixo"&&p.setor===sector);
    const split=(p:EscalaColaborador)=>{const pt=activePattern(p);return !!pt&&isDuasUnidades(pt);};
    // Quem divide os dias entre as unidades faz o mês das duas unidades ser gerado junto
    const targets:("Botafogo"|"Ipanema")[]=fixos.some(p=>p.unidade==="Ambas"&&split(p))?["Botafogo","Ipanema"]:[unit];
    const missing:string[]=[];const adjusted:string[]=[];const byUnit=new Map<"Botafogo"|"Ipanema",{colaborador_id:string;data:string;status:"trabalho"|"folga";turno:"manha"|"noite"|"dia";hora_entrada:string|null;hora_saida:string|null}[]>();
    for(const u of targets){const rows:{colaborador_id:string;data:string;status:"trabalho"|"folga";turno:"manha"|"noite"|"dia";hora_entrada:string|null;hora_saida:string|null}[]=[];
      for(const person of fixos.filter(p=>appliesTo(p,u))){const isSplit=person.unidade==="Ambas"&&split(person);if(!isSplit&&u!==unit)continue;const p=activePattern(person);if(!p){if(u===unit)missing.push(`${person.nome}: padrão`);continue;}if(p.tipo!=="5x2_fixo"&&!p.data_base){if(u===unit)missing.push(`${person.nome}: data-base`);continue;}if(u===unit&&p.tipo==="5x2_revezamento"&&resolveRevezamento(p).ajustado)adjusted.push(person.nome);
        const gen=isSplit?generatePatternMonthUnits(p,year,month).filter(d=>d.unidade===u).map(({data,status})=>({data,status})):generatePatternMonth(p,year,month);
        for(const d of gen)rows.push({...d,colaborador_id:person.id,turno:person.turno_padrao??"dia",hora_entrada:p.hora_entrada,hora_saida:p.hora_saida});}
      byUnit.set(u,rows);}
    if(missing.length)return toast.error("Complete os padrões antes de gerar",{description:missing.join(" · ")});
    try{let total=0;for(const u of targets){const rows=byUnit.get(u)??[];total+=rows.length;await generate.mutateAsync({unidade:u,setor:sector,competencia:bounds.start,dias:rows});}
      toast.success("Escala do mês gerada",{description:`${total} dias calculados sem reiniciar o ciclo.${targets.length>1?" Botafogo e Ipanema geradas juntas (há quem trabalhe nas duas).":""}${adjusted.length?` Folgas ajustadas às regras do revezamento: ${adjusted.join(", ")} (veja o cadastro).`:""}`});setRegenerate(false);}catch(e){toast.error(e instanceof Error?e.message:"Não foi possível gerar");}};
  const publishNow=async(justificativa?:string)=>{if(unit==="Ambas")return;try{await publish.mutateAsync({unidade:unit,setor:sector,competencia:bounds.start,justificativa:justificativa||null});toast.success("Escala publicada",{description:"Os colaboradores vinculados receberam uma notificação."});setPublishOverride(null);setPublishReason("");}catch(e){toast.error(e instanceof Error?e.message:"Não foi possível publicar");}};
  const doPublish=()=>{if(unit==="Ambas")return toast.error("Publique cada unidade separadamente.");if(!days.length)return toast.error("Gere a escala antes de publicar.");const red=issues.filter(i=>i.severity==="error"&&(!i.date||(i.date>=bounds.start&&i.date<=bounds.end)));if(red.length){setPublishOverride(red);return;}void publishNow();};
  const persist=async(patches:EscalaDiaInput[])=>{try{await saveMany.mutateAsync(patches);toast.success("Escala atualizada");setEdit(null);setOverride(null);setReason("");}catch(e){toast.error(e instanceof Error?e.message:"Não foi possível salvar");}};
  const validateThenSave=(patches:EscalaDiaInput[])=>{const patched=contextDays.filter(d=>!patches.some(p=>p.colaborador_id===d.colaborador_id&&p.data===d.data&&p.turno===d.turno)).concat(patches.map((p,i)=>({...p,id:`new-${i}`,created_at:"",updated_at:"",updated_by:null})));const next=buildIssues(allPeople,patched,holidays,sector,units).filter(i=>i.severity==="error"&&patches.some(p=>p.colaborador_id===i.personId&&(p.data===i.date||Math.abs(new Date(`${p.data}T00:00:00Z`).getTime()-new Date(`${i.date}T00:00:00Z`).getTime())<=7*86400000)));if(next.length)setOverride({patches,errors:next});else void persist(patches);};
  const swap=(source:EscalaDia,targetDate:string)=>{const target=days.find(d=>d.colaborador_id===source.colaborador_id&&d.data===targetDate&&d.turno===source.turno);const base=(row:EscalaDia,status:EscalaDia["status"],date=row.data):EscalaDiaInput=>({colaborador_id:row.colaborador_id,unidade:row.unidade,setor:row.setor,data:date,turno:row.turno,hora_entrada:row.hora_entrada,hora_saida:row.hora_saida,status,origem:"manual",substitui_colaborador_id:row.substitui_colaborador_id,motivo:"Troca por arrastar e soltar",modalidade_id:row.modalidade_id,motivo_chamada:row.motivo_chamada,horas_contratadas:row.horas_contratadas,valor_combinado:row.valor_combinado});validateThenSave([base(source,target?.status??"folga"),base(source,source.status,targetDate)]);};
  if(loading)return <p className="py-10 text-center text-sm text-muted-foreground">Carregando escala…</p>;
  return <div className="space-y-4">
    <div className="flex flex-wrap items-center justify-between gap-2 print:hidden"><div className="flex items-center gap-2"><Badge variant={publication==="publicada"?"default":"secondary"}>{publication==="publicada"?"Publicada":"Rascunho"}</Badge><span className="text-xs text-muted-foreground">{days.length} registros</span></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={()=>generatedCount?setRegenerate(true):void doGenerate()} disabled={generate.isPending}><Sparkles className="mr-2 h-4 w-4"/>Gerar escala do mês</Button><Button variant="outline" onClick={()=>unit==="Ambas"?toast.error("Selecione Botafogo ou Ipanema."):setFeriasOpen(true)}><Palmtree className="mr-2 h-4 w-4"/>Férias</Button><Button variant="outline" onClick={()=>unit==="Ambas"?toast.error("Selecione Botafogo ou Ipanema."):setCoverOpen(true)}><UserCheck className="mr-2 h-4 w-4"/>Cobrir folgas com freelancer</Button><Button onClick={doPublish} disabled={publish.isPending||unit==="Ambas"}><Send className="mr-2 h-4 w-4"/>Publicar escala do mês</Button></div></div>
    <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_300px]"> <div className="min-w-0">{view==="calendar"?<ScheduleCalendar year={year} month={month} days={days} people={allPeople} holidays={holidays} onEdit={(p,date,row)=>setEdit({person:p,date,row})} onFree={(date,u)=>setFree({date,unit:u})} onSwap={swap}/>:<PersonGrid year={year} month={month} people={people} days={days} holidays={holidays} onEdit={(p,date,row)=>setEdit({person:p,date,row})}/>}</div><WarningsPanel issues={issues} onFree={(date,u)=>date&&u&&setFree({date,unit:u})}/></div>
    <MonthlySummary people={people} days={days} modalities={modalities.data??[]}/>
    <EditDayDialog data={edit} requireReason={publication==="publicada"} onClose={()=>setEdit(null)} onSave={validateThenSave} onCover={(date,u,id)=>setFree({date,unit:u,replaces:id})}/>
    <FreelancerDialog data={free} people={allPeople} modalities={modalities.data??[]} days={days} contextDays={contextDays} sector={sector} onClose={()=>setFree(null)} onSave={input=>save.mutate(input,{onSuccess:()=>{toast.success("Extra lançado na escala");setFree(null);},onError:e=>toast.error(e.message)})}/>
    {feriasOpen&&unit!=="Ambas"&&<FeriasDialog unit={unit} people={allPeople} days={contextDays} modalities={modalities.data??[]} onClose={()=>setFeriasOpen(false)}/>}
    {coverOpen&&unit!=="Ambas"&&<CoverDaysOffDialog unit={unit} start={bounds.start} end={bounds.end} people={allPeople} days={contextDays} modalities={modalities.data??[]} onClose={()=>setCoverOpen(false)}/>}
    <Dialog open={regenerate} onOpenChange={setRegenerate}><DialogContent><DialogHeader><DialogTitle>Regerar só os dias automáticos?</DialogTitle><DialogDescription>Faltas, trocas, freelancers e outras alterações manuais serão preservadas.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={()=>setRegenerate(false)}>Cancelar</Button><Button onClick={doGenerate}>Regerar automáticos</Button></DialogFooter></DialogContent></Dialog>
    <Dialog open={!!override} onOpenChange={v=>!v&&(setOverride(null),setReason(""))}><DialogContent><DialogHeader><DialogTitle className="text-destructive">Confirmar exceção na escala</DialogTitle><DialogDescription>{override?.errors.map(e=>e.message).join(" ")}</DialogDescription></DialogHeader><div className="space-y-2"><Label>Motivo obrigatório</Label><Textarea value={reason} onChange={e=>setReason(e.target.value)} placeholder="Explique por que esta exceção será mantida"/></div><DialogFooter><Button variant="outline" onClick={()=>setOverride(null)}>Cancelar</Button><Button disabled={reason.trim().length<3} onClick={()=>override&&void persist(override.patches.map(p=>({...p,motivo:reason.trim()})))}>Salvar mesmo assim</Button></DialogFooter></DialogContent></Dialog>
    <Dialog open={!!publishOverride} onOpenChange={v=>!v&&(setPublishOverride(null),setPublishReason(""))}><DialogContent><DialogHeader><DialogTitle className="text-destructive">A escala tem erros vermelhos</DialogTitle><DialogDescription>Revise os erros abaixo ou informe uma justificativa para publicar mesmo assim.</DialogDescription></DialogHeader><div className="max-h-48 space-y-2 overflow-y-auto">{publishOverride?.map(item=><div key={item.id} className="rounded-md border border-destructive/30 bg-destructive/10 p-2 text-sm">{item.message}</div>)}</div><div className="space-y-2"><Label>Justificativa obrigatória</Label><Textarea value={publishReason} onChange={e=>setPublishReason(e.target.value)} placeholder="Explique por que a escala será publicada com essas exceções"/></div><DialogFooter><Button variant="outline" onClick={()=>setPublishOverride(null)}>Voltar e corrigir</Button><Button disabled={publishReason.trim().length<5||publish.isPending} onClick={()=>void publishNow(publishReason.trim())}>Publicar com justificativa</Button></DialogFooter></DialogContent></Dialog>
  </div>;
}

function ScheduleCalendar({year,month,days,people,holidays,onEdit,onFree,onSwap}:{year:number;month:number;days:EscalaDia[];people:EscalaColaborador[];holidays:{data:string;nome:string}[];onEdit:(p:EscalaColaborador,date:string,row?:EscalaDia)=>void;onFree:(date:string,u:"Botafogo"|"Ipanema")=>void;onSwap:(source:EscalaDia,date:string)=>void}){const [mostrarValores]=useMostrarValores();const bounds=monthBounds(year,month);const dates=civilRange(bounds.start,bounds.end);const leading=civilDow(bounds.start);const holidayMap=new Map(holidays.map(h=>[h.data,h.nome]));return <div className="overflow-hidden rounded-md border"><div className="grid grid-cols-7 bg-muted/50 text-center text-[11px] font-semibold uppercase text-muted-foreground">{["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"].map(d=><div key={d} className="p-2">{d}</div>)}</div><div className="grid grid-cols-7">{Array.from({length:leading}).map((_,i)=><div key={`blank-${i}`} className="min-h-28 border-l border-t bg-muted/20"/>)}{dates.map(date=>{const dateRows=days.filter(d=>d.data===date);return <div key={date} id={`schedule-${date}`} className={cn("min-h-28 border-l border-t p-1.5",holidayMap.has(date)&&"bg-warning/10")} onDragOver={e=>e.preventDefault()} onDrop={e=>{const raw=e.dataTransfer.getData("application/json");if(raw){try{onSwap(JSON.parse(raw) as EscalaDia,date);}catch{return;}}}}><div className="mb-1 flex items-center justify-between"><span className="text-[11px] font-semibold">{date.slice(-2)}</span>{holidayMap.has(date)&&<span title={holidayMap.get(date)} className="h-2 w-2 rounded-full bg-warning"/>}</div><div className="space-y-1">{dateRows.filter(d=>d.status!=="folga").map(row=>{const person=people.find(p=>p.id===row.colaborador_id);if(!person)return null;return <button key={row.id} type="button" draggable onDragStart={e=>e.dataTransfer.setData("application/json",JSON.stringify(row))} onClick={()=>onEdit(person,date,row)} className={cn("flex w-full items-center justify-between gap-1 rounded border px-1.5 py-1 text-left text-[10px]",row.status==="falta"||row.status==="atestado"?"border-destructive/30 bg-destructive/10":row.modalidade_id?"border-warning/40 bg-warning/10":"border-primary/20 bg-primary/5")}><span className="truncate">{person.nome}</span><span className="shrink-0 font-semibold">{row.modalidade_id?(mostrarValores?`${row.horas_contratadas}h · ${money(Number(row.valor_combinado??0))}`:`Extra ${row.horas_contratadas}h`):STATUS_CODE[row.status]}</span></button>})}{dateRows.length===0&&<span className="text-[10px] text-muted-foreground">—</span>}{dateRows[0]&&<Button size="sm" variant="ghost" className="h-6 w-full text-[10px]" onClick={()=>onFree(date,dateRows[0].unidade)}><Plus className="mr-1 h-3 w-3"/>Freelancer</Button>}</div></div>})}</div></div>}

function PersonGrid({year,month,people,days,holidays,onEdit}:{year:number;month:number;people:EscalaColaborador[];days:EscalaDia[];holidays:{data:string}[];onEdit:(p:EscalaColaborador,date:string,row?:EscalaDia)=>void}){const b=monthBounds(year,month),dates=civilRange(b.start,b.end),hs=new Set(holidays.map(h=>h.data));return <div className="overflow-x-auto rounded-md border"><table className="min-w-max text-xs"><thead><tr className="bg-muted/50"><th className="sticky left-0 z-10 min-w-44 bg-muted px-3 py-2 text-left">Pessoa</th>{dates.map(d=><th key={d} className={cn("w-9 px-1 py-2 text-center",([0,6].includes(civilDow(d))||hs.has(d))&&"bg-warning/10")}>{Number(d.slice(-2))}</th>)}</tr></thead><tbody>{people.map(p=><tr key={p.id} className="border-t"><td className="sticky left-0 z-10 bg-card px-3 py-2 font-medium">{p.nome}</td>{dates.map(date=>{const row=days.find(d=>d.colaborador_id===p.id&&d.data===date);return <td key={date} className={cn("border-l p-0 text-center",([0,6].includes(civilDow(date))||hs.has(date))&&"bg-warning/5")}><button type="button" className={cn("h-8 w-9 font-semibold",row?.status==="trabalho"&&"text-primary",row?.status==="falta"&&"text-destructive",row?.status==="atestado"&&"text-warning-foreground")} onClick={()=>onEdit(p,date,row)}>{row?STATUS_CODE[row.status]:"·"}</button></td>})}</tr>)}</tbody></table></div>}

function EditDayDialog({data,requireReason,onClose,onSave,onCover}:{data:{person:EscalaColaborador;date:string;row?:EscalaDia}|null;requireReason:boolean;onClose:()=>void;onSave:(p:EscalaDiaInput[])=>void;onCover:(date:string,u:"Botafogo"|"Ipanema",id:string)=>void}){const [status,setStatus]=useState<EscalaDia["status"]>("trabalho"),[entry,setEntry]=useState(""),[exit,setExit]=useState(""),[reason,setReason]=useState("");const key=data?`${data.person.id}-${data.date}-${data.row?.updated_at??"new"}`:"none";return <Dialog key={key} open={!!data} onOpenChange={v=>!v&&onClose()}><DialogContent><DialogHeader><DialogTitle>Editar dia</DialogTitle><DialogDescription>{data?.person.nome} · {data?.date.split("-").reverse().join("/")}{requireReason?" · escala já publicada":""}</DialogDescription></DialogHeader>{data&&<EditDayForm initial={data.row} status={status} setStatus={setStatus} entry={entry} setEntry={setEntry} exit={exit} setExit={setExit} reason={reason} setReason={setReason}/>}<DialogFooter className="flex-wrap">{data&&(status==="falta"||status==="atestado")&&<Button variant="outline" onClick={()=>{const unit=data.row?.unidade??(data.person.unidade==="Ipanema"?"Ipanema":"Botafogo");onClose();onCover(data.date,unit,data.person.id);}}>Chamar freelancer</Button>}<Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={!data||(requireReason&&reason.trim().length<3)} onClick={()=>{if(!data)return;const unit=data.row?.unidade??(data.person.unidade==="Ipanema"?"Ipanema":"Botafogo");onSave([{colaborador_id:data.person.id,unidade:unit,setor:data.person.setor,data:data.date,turno:data.person.turno_padrao??"dia",hora_entrada:entry||data.row?.hora_entrada||null,hora_saida:exit||data.row?.hora_saida||null,status,origem:"manual",substitui_colaborador_id:null,motivo:reason||null,modalidade_id:null,motivo_chamada:null,horas_contratadas:null,valor_combinado:null}]);}}>Salvar</Button></DialogFooter></DialogContent></Dialog>}
function EditDayForm({initial,status,setStatus,entry,setEntry,exit,setExit,reason,setReason}:{initial?:EscalaDia;status:EscalaDia["status"];setStatus:(s:EscalaDia["status"])=>void;entry:string;setEntry:(s:string)=>void;exit:string;setExit:(s:string)=>void;reason:string;setReason:(s:string)=>void}){useState(()=>{setStatus(initial?.status??"trabalho");setEntry(initial?.hora_entrada?.slice(0,5)??"");setExit(initial?.hora_saida?.slice(0,5)??"");setReason(initial?.motivo??"");});return <div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2 sm:col-span-2"><Label>Situação</Label><Select value={status} onValueChange={v=>setStatus(v as EscalaDia["status"])}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{Object.entries(STATUS_LABEL).map(([v,l])=><SelectItem key={v} value={v}>{l}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Entrada</Label><Input type="time" value={entry} onChange={e=>setEntry(e.target.value)}/></div><div className="space-y-2"><Label>Saída</Label><Input type="time" value={exit} onChange={e=>setExit(e.target.value)}/></div><div className="space-y-2 sm:col-span-2"><Label>Motivo / observação</Label><Textarea value={reason} onChange={e=>setReason(e.target.value)}/></div></div>}

function FreelancerDialog({data,people,modalities,days,contextDays,sector,onClose,onSave}:{data:{date:string;unit:"Botafogo"|"Ipanema";replaces?:string}|null;people:EscalaColaborador[];modalities:ReturnType<typeof useEscalaModalidades>["data"];days:EscalaDia[];contextDays:EscalaDia[];sector:EscalaSetor;onClose:()=>void;onSave:(i:EscalaDiaInput)=>void}){const frees=people.filter(p=>p.ativo&&p.vinculo==="freelance"&&data&&(p.unidade===data.unit||p.unidade==="Ambas"));
  // Fixos do setor que estão de folga nesse dia (em qualquer unidade) podem ser chamados como extra, pagos como freelancer
  const fixosFolga=people.filter(p=>p.ativo&&p.vinculo==="fixo"&&p.setor===sector&&data&&(p.unidade===data.unit||p.unidade==="Ambas")&&(()=>{const rows=contextDays.filter(d=>d.colaborador_id===p.id&&d.data===data.date);return rows.length>0&&rows.every(d=>d.status==="folga");})());
  const candidates=[...frees,...fixosFolga];const available=(modalities??[]).filter(m=>m.ativo&&data&&(m.unidade===data.unit||m.unidade==="Ambas"));const absence=data?days.find(d=>d.data===data.date&&d.unidade===data.unit&&(d.status==="falta"||d.status==="atestado")):undefined;const suggested=available.find(m=>m.motivo===(absence||data?.replaces?"cobertura_falta":"reforco_ocupacao"))??available[0];const [personId,setPersonId]=useState(""),[modalityId,setModalityId]=useState(suggested?.id??""),[entry,setEntry]=useState("08:00"),[hours,setHours]=useState(String(suggested?.horas??8)),[value,setValue]=useState(String(suggested?.valor??0)),[note,setNote]=useState("");const selected=available.find(m=>m.id===modalityId)??suggested;const selectMod=(id:string)=>{const m=available.find(x=>x.id===id);setModalityId(id);if(m){setHours(String(m.horas));setValue(String(m.valor));}};return <Dialog key={data?`${data.date}-${data.unit}`:"none"} open={!!data} onOpenChange={v=>!v&&onClose()}><DialogContent className="sm:max-w-xl"><DialogHeader><DialogTitle>Chamar freelancer ou fixo (extra)</DialogTitle><DialogDescription>{data?.unit} · {data?.date.split("-").reverse().join("/")}</DialogDescription></DialogHeader><div className="space-y-4"><div className="space-y-2"><Label>Quem vai trabalhar</Label><Select value={personId} onValueChange={setPersonId}><SelectTrigger><SelectValue placeholder="Selecionar"/></SelectTrigger><SelectContent>{frees.map(p=><SelectItem key={p.id} value={p.id}>{p.nome} · freelancer</SelectItem>)}{fixosFolga.map(p=><SelectItem key={p.id} value={p.id}>{p.nome} · fixo, de folga (extra)</SelectItem>)}</SelectContent></Select>{fixosFolga.some(p=>p.id===personId)&&<p className="text-xs text-muted-foreground">A folga dele neste dia vira um dia extra pago (vai para o Financeiro como os freelancers). Para desfazer, edite o dia e volte para Folga.</p>}</div><div className="grid gap-2">{available.map(m=><Button key={m.id} variant={modalityId===m.id||(!modalityId&&suggested?.id===m.id)?"default":"outline"} className="h-auto justify-start py-3 text-left" onClick={()=>selectMod(m.id)}>{m.nome} · {m.horas} h · {money(Number(m.valor))}</Button>)}</div><div className="grid gap-3 sm:grid-cols-3"><div className="space-y-2"><Label>Entrada</Label><Input type="time" value={entry} onChange={e=>setEntry(e.target.value)}/></div><div className="space-y-2"><Label>Horas</Label><Input type="number" step="0.5" value={hours} onChange={e=>setHours(e.target.value)}/></div><div className="space-y-2"><Label>Valor</Label><Input type="number" step="0.01" value={value} onChange={e=>setValue(e.target.value)}/></div></div><p className="text-sm text-muted-foreground">Saída calculada: {calculateEndTime(entry,Number(hours)||0)}</p><div className="space-y-2"><Label>Observação</Label><Textarea value={note} onChange={e=>setNote(e.target.value)}/></div></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={!data||!personId||!selected} onClick={()=>{if(!data||!selected)return;const person=candidates.find(p=>p.id===personId);if(!person)return;onSave({colaborador_id:person.id,unidade:data.unit,setor:person.setor,data:data.date,turno:person.turno_padrao??"dia",hora_entrada:entry,hora_saida:calculateEndTime(entry,Number(hours)),status:"extra",origem:"manual",substitui_colaborador_id:data.replaces??absence?.colaborador_id??null,motivo:note||null,modalidade_id:selected.id,motivo_chamada:selected.motivo,horas_contratadas:Number(hours),valor_combinado:Number(value)});}}>Adicionar plantão</Button></DialogFooter></DialogContent></Dialog>}

function WarningsPanel({issues,onFree}:{issues:ScheduleIssue[];onFree:(d?:string,u?:"Botafogo"|"Ipanema")=>void}){return <aside className="space-y-2 print:hidden"><h3 className="flex items-center gap-2 font-semibold"><AlertTriangle className="h-4 w-4"/>Avisos ({issues.length})</h3><div className="max-h-[520px] space-y-2 overflow-y-auto">{issues.length===0?<div className="rounded-md border border-success/30 bg-success/10 p-3 text-sm"><CheckCircle2 className="mr-2 inline h-4 w-4"/>Nenhum aviso.</div>:issues.slice(0,80).map(i=><div key={i.id} className={cn("rounded-md border p-3 text-xs",i.severity==="error"?"border-destructive/30 bg-destructive/10":"border-warning/40 bg-warning/10")}><a href={i.date?`#schedule-${i.date}`:undefined} className="font-medium">{i.message}</a>{i.date&&<p className="mt-1 text-muted-foreground">{i.date.split("-").reverse().join("/")}</p>}{i.code==="uncovered"&&i.date&&i.unidade&&<Button size="sm" variant="outline" className="mt-2 h-7 text-xs" onClick={()=>onFree(i.date,i.unidade)}>Escalar freelancer</Button>}</div>)}</div></aside>}

function MonthlySummary({people,days,modalities}:{people:EscalaColaborador[];days:EscalaDia[];modalities:{id:string;nome:string}[]}){const [mostrarValores]=useMostrarValores();const perPerson=people.map(p=>{const mine=days.filter(d=>d.colaborador_id===p.id);return {id:p.id,nome:p.nome,work:mine.filter(d=>d.status==="trabalho"||d.status==="extra").length,off:mine.filter(d=>d.status==="folga").length,sundays:mine.filter(d=>d.status==="folga"&&civilDow(d.data)===0).length,absence:mine.filter(d=>d.status==="falta").length};});const free=days.filter(d=>d.modalidade_id).reduce<Record<string,{count:number;hours:number;value:number}>>((acc,d)=>{const k=d.modalidade_id??"";acc[k]??={count:0,hours:0,value:0};acc[k].count++;acc[k].hours+=Number(d.horas_contratadas??0);acc[k].value+=Number(d.valor_combinado??0);return acc;},{});return <div className="grid gap-4 lg:grid-cols-2"><Card className="p-4"><h3 className="mb-3 font-semibold">Resumo por pessoa</h3><div className="space-y-2">{perPerson.map(p=><div key={p.id} className="grid grid-cols-[1fr_repeat(4,auto)] gap-3 border-b py-2 text-xs"><span className="truncate font-medium">{p.nome}</span><span>{p.work} T</span><span>{p.off} F</span><span>{p.sundays} Dom</span><span>{p.absence} FT</span></div>)}</div></Card><Card className="p-4"><h3 className="mb-3 font-semibold">Freelancers do mês</h3>{Object.keys(free).length===0?<p className="text-sm text-muted-foreground">Nenhum plantão lançado.</p>:Object.entries(free).map(([id,v])=><div key={id} className="flex justify-between border-b py-2 text-sm"><span>{modalities.find(m=>m.id===id)?.nome??"Modalidade"}</span><span>{v.count} · {v.hours}h{mostrarValores?` · ${money(v.value)}`:""}</span></div>)}</Card></div>}

function WhatsApp({days,people,label}:{days:EscalaDia[];people:EscalaColaborador[];label:string}){const [open,setOpen]=useState(false);const line=(p:EscalaColaborador)=>{const mine=days.filter(d=>d.colaborador_id===p.id);const off=mine.filter(d=>d.status==="folga").map(d=>Number(d.data.slice(-2)));const work=mine.filter(d=>d.status==="trabalho"||d.status==="extra").map(d=>Number(d.data.slice(-2)));return `*${p.nome.toUpperCase()}* — folgas: ${off.join(", ")||"nenhuma"}; trabalho: ${work.join(", ")||"nenhum"}`};const teamText=encodeURIComponent(`*Escala INJOY — ${label}*\n\n${people.map(line).join("\n")}`);const phone=(value:string|null)=>value?.replace(/\D/g,"")??"";return <><Button variant="outline" onClick={()=>setOpen(true)}><MessageCircle className="mr-2 h-4 w-4"/>WhatsApp</Button><Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Compartilhar escala</DialogTitle><DialogDescription>Envie o resumo completo ou somente a escala de uma pessoa.</DialogDescription></DialogHeader><Button asChild><a href={`https://wa.me/?text=${teamText}`} target="_blank" rel="noreferrer">Enviar equipe completa</a></Button><div className="max-h-72 space-y-2 overflow-y-auto">{people.map(p=><Button key={p.id} variant="outline" className="w-full justify-between" disabled={!phone(p.telefone)} asChild={!!phone(p.telefone)}>{phone(p.telefone)?<a href={`https://wa.me/${phone(p.telefone)}?text=${encodeURIComponent(`*Escala INJOY — ${label}*\n\n${line(p)}`)}`} target="_blank" rel="noreferrer"><span>{p.nome}</span><span className="text-xs">Enviar</span></a>:<span><span>{p.nome}</span><span className="text-xs">Sem telefone</span></span>}</Button>)}</div></DialogContent></Dialog></>}

function buildIssues(people:EscalaColaborador[],days:EscalaDia[],holidays:{data:string}[],sector:EscalaSetor,units:("Botafogo"|"Ipanema")[]):ScheduleIssue[]{const inputs:ValidationPerson[]=[];for(const person of people.filter(p=>p.ativo&&p.setor===sector)){const freelance=person.vinculo==="freelance";const pattern=activePattern(person)??(freelance?{tipo:"5x2_fixo" as const,data_base:null,folgas_fixas:[],folga_semana_a:null,folga_semana_b:null}:null);if(!pattern)continue;for(const unit of units){if(person.unidade!=="Ambas"&&person.unidade!==unit)continue;inputs.push({id:person.id,nome:person.nome,setor:person.setor,unidade:unit,turno:person.turno_padrao??"dia",pattern,freelance,days:days.filter(d=>d.colaborador_id===person.id&&d.unidade===unit).map(d=>({data:d.data,status:d.status,hora_entrada:d.hora_entrada,hora_saida:d.hora_saida,origem:d.origem}))});}}return validateSchedule(inputs,holidays.map(h=>h.data)).filter(i=>{
  // Só os avisos da aba e da(s) unidade(s) abertas
  if(i.unidade&&!units.includes(i.unidade))return false;
  if(i.code!=="uncovered")return true;
  if(i.id.startsWith("uncovered-cam-"))return sector==="camareiras";
  // Ipanema não tem recepção fixa: não avisa recepção sem cobertura lá
  if(i.id.startsWith("uncovered-rec-"))return sector==="recepcao"&&i.unidade!=="Ipanema";
  return true;
});}

/** Escala uma freelancer em todas as folgas de uma pessoa fixa no mês (ex.: Cristina nas folgas da Maria). */
function CoverDaysOffDialog({unit,start,end,people,days,modalities,onClose}:{unit:"Botafogo"|"Ipanema";start:string;end:string;people:EscalaColaborador[];days:EscalaDia[];modalities:NonNullable<ReturnType<typeof useEscalaModalidades>["data"]>;onClose:()=>void}){
  const saveMany=useSalvarEscalaDias(); const remove=useExcluirEscalaDias();
  const inUnit=(p:EscalaColaborador)=>p.ativo&&(p.unidade===unit||p.unidade==="Ambas");
  const fixos=people.filter(p=>inUnit(p)&&p.vinculo==="fixo"); const frees=people.filter(p=>inUnit(p)&&p.vinculo==="freelance");
  const available=modalities.filter(m=>m.ativo&&(m.unidade===unit||m.unidade==="Ambas"));
  const [fixedId,setFixedId]=useState(""),[freeId,setFreeId]=useState(""),[modalityId,setModalityId]=useState(available.find(m=>m.motivo==="reforco_ocupacao")?.id??available[0]?.id??"");
  const modality=available.find(m=>m.id===modalityId);
  const fixed=fixos.find(p=>p.id===fixedId); const pattern=fixed?activePattern(fixed):null;
  const [entry,setEntry]=useState(""),[hours,setHours]=useState(modality?String(modality.horas):"8"),[value,setValue]=useState(modality?String(modality.valor):"0");
  const selectMod=(id:string)=>{const m=available.find(x=>x.id===id);setModalityId(id);if(m){setHours(String(m.horas));setValue(String(m.valor));}};
  const entrada=entry||pattern?.hora_entrada?.slice(0,5)||"08:00";
  const inMonth=(d:EscalaDia)=>d.data>=start&&d.data<=end&&d.unidade===unit;
  const offDates=fixedId?days.filter(d=>inMonth(d)&&d.colaborador_id===fixedId&&d.status==="folga").map(d=>d.data).sort():[];
  const coverage=(d:EscalaDia)=>d.colaborador_id===freeId&&d.status==="extra"&&d.substitui_colaborador_id===fixedId&&(d.motivo??"").startsWith("Cobertura de folga");
  const busy=freeId?days.filter(d=>d.colaborador_id===freeId&&offDates.includes(d.data)&&!coverage(d)).map(d=>d.data):[];
  const targets=offDates.filter(d=>!busy.includes(d));
  const stale=freeId&&fixedId?days.filter(d=>inMonth(d)&&coverage(d)&&!offDates.includes(d.data)):[];
  const fmt=(d:string)=>`${d.slice(8,10)}/${d.slice(5,7)}`;
  const submit=async()=>{if(!fixed||!modality||!freeId)return;const free=frees.find(p=>p.id===freeId);if(!free)return;
    const rows:EscalaDiaInput[]=targets.map(data=>({colaborador_id:free.id,unidade:unit,setor:fixed.setor,data,turno:free.turno_padrao??"dia",hora_entrada:entrada,hora_saida:calculateEndTime(entrada,Number(hours)||0),status:"extra",origem:"manual",substitui_colaborador_id:fixed.id,motivo:`Cobertura de folga — ${fixed.nome}`,modalidade_id:modality.id,motivo_chamada:modality.motivo,horas_contratadas:Number(hours),valor_combinado:Number(value)}));
    try{if(rows.length)await saveMany.mutateAsync(rows);if(stale.length)await remove.mutateAsync(stale.map(d=>d.id));toast.success(`${free.nome} escalada em ${rows.length} folga(s) de ${fixed.nome}`,{description:[stale.length?`${stale.length} cobertura(s) antiga(s) removida(s).`:"",busy.length?`Não escalada em ${busy.map(fmt).join(", ")}: já tem outro registro nesses dias.`:""].filter(Boolean).join(" ")||undefined});onClose();}catch(e){toast.error(e instanceof Error?e.message:"Não foi possível salvar");}};
  return <Dialog open onOpenChange={v=>!v&&onClose()}><DialogContent className="sm:max-w-xl"><DialogHeader><DialogTitle>Cobrir folgas com freelancer</DialogTitle><DialogDescription>{unit} · {MONTHS[Number(start.slice(5,7))-1]} de {start.slice(0,4)}. Gere a escala do mês antes; se as folgas mudarem, rode de novo para atualizar.</DialogDescription></DialogHeader>
    <div className="space-y-4">
      <div className="grid gap-3 sm:grid-cols-2"><div className="space-y-2"><Label>Folgas de</Label><Select value={fixedId} onValueChange={setFixedId}><SelectTrigger><SelectValue placeholder="Selecionar"/></SelectTrigger><SelectContent>{fixos.map(p=><SelectItem key={p.id} value={p.id}>{p.nome}</SelectItem>)}</SelectContent></Select></div>
      <div className="space-y-2"><Label>Freelancer</Label><Select value={freeId} onValueChange={setFreeId}><SelectTrigger><SelectValue placeholder="Selecionar"/></SelectTrigger><SelectContent>{frees.map(p=><SelectItem key={p.id} value={p.id}>{p.nome}</SelectItem>)}</SelectContent></Select>{frees.length===0&&<p className="text-xs text-muted-foreground">Nenhuma freelancer ativa nesta unidade. Cadastre em Equipe da Escala.</p>}</div></div>
      <div className="grid gap-2">{available.map(m=><Button key={m.id} variant={modalityId===m.id?"default":"outline"} className="h-auto justify-start py-3 text-left" onClick={()=>selectMod(m.id)}>{m.nome} · {m.horas} h · {money(Number(m.valor))}</Button>)}</div>
      <div className="grid gap-3 sm:grid-cols-3"><div className="space-y-2"><Label>Entrada</Label><Input type="time" value={entrada} onChange={e=>setEntry(e.target.value)}/></div><div className="space-y-2"><Label>Horas</Label><Input type="number" step="0.5" value={hours} onChange={e=>setHours(e.target.value)}/></div><div className="space-y-2"><Label>Valor por dia</Label><Input type="number" step="0.01" value={value} onChange={e=>setValue(e.target.value)}/></div></div>
      {fixedId&&<div className="rounded-md border p-3 text-sm">{offDates.length===0?<p className="text-muted-foreground">Nenhuma folga encontrada neste mês. Gere a escala primeiro.</p>:<><p><strong>{targets.length}</strong> dia(s): {targets.map(fmt).join(", ")||"—"}</p><p className="mt-1 text-muted-foreground">Total: {money(targets.length*(Number(value)||0))} · saída {calculateEndTime(entrada,Number(hours)||0)}</p>{busy.length>0&&<p className="mt-1 text-amber-700">Já tem outro registro em {busy.map(fmt).join(", ")}; esses dias ficam como estão.</p>}{stale.length>0&&<p className="mt-1 text-amber-700">Será removida a cobertura em {stale.map(d=>fmt(d.data)).join(", ")} (não é mais folga).</p>}</>}</div>}
    </div>
    <DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={!fixedId||!freeId||!modality||(targets.length===0&&stale.length===0)||saveMany.isPending||remove.isPending} onClick={()=>void submit()}>Escalar nas folgas</Button></DialogFooter>
  </DialogContent></Dialog>;
}

/** Lançar férias de quem é fixo e escalar automaticamente uma freelancer nos dias em que a pessoa trabalharia. */
function FeriasDialog({unit,people,days,modalities,onClose}:{unit:"Botafogo"|"Ipanema";people:EscalaColaborador[];days:EscalaDia[];modalities:NonNullable<ReturnType<typeof useEscalaModalidades>["data"]>;onClose:()=>void}){
  const ferias=useEscalaFerias(); const salvar=useSalvarFerias(); const excluir=useExcluirFerias();
  const inUnit=(p:EscalaColaborador)=>p.ativo&&(p.unidade===unit||p.unidade==="Ambas");
  const fixos=people.filter(p=>inUnit(p)&&p.vinculo==="fixo"&&activePattern(p)); const frees=people.filter(p=>inUnit(p)&&p.vinculo==="freelance");
  const available=modalities.filter(m=>m.ativo&&(m.unidade===unit||m.unidade==="Ambas"));
  const today=todaySP();
  const [editing,setEditing]=useState<string|null>(null),[confirmDelete,setConfirmDelete]=useState<string|null>(null);
  const [colabId,setColabId]=useState(""),[inicio,setInicio]=useState(today),[fim,setFim]=useState(addCivilDays(today,29)),[subId,setSubId]=useState("none"),[modId,setModId]=useState(""),[entrada,setEntrada]=useState("08:00"),[horas,setHoras]=useState("8"),[valor,setValor]=useState("0"),[obs,setObs]=useState("");
  const [fx,setFx]=useState(false),[fxModId,setFxModId]=useState(""),[fxEntrada,setFxEntrada]=useState("08:00"),[fxHoras,setFxHoras]=useState("8"),[fxValor,setFxValor]=useState("150");
  const fxMod=available.find(m=>m.id===fxModId);
  const applyFxMod=(m?:typeof available[number])=>{if(!m)return;setFxModId(m.id);setFxHoras(String(m.horas));setFxValor(String(m.valor));};
  const colab=fixos.find(p=>p.id===colabId)??people.find(p=>p.id===colabId); const pattern=colab?activePattern(colab):null;
  const modalidade=available.find(m=>m.id===modId);
  const nome=(id:string|null)=>people.find(p=>p.id===id)?.nome??"—"; const fmt=(d:string)=>`${d.slice(8,10)}/${d.slice(5,7)}/${d.slice(2,4)}`;
  const applyMod=(m?:typeof available[number])=>{if(!m)return;setModId(m.id);setHoras(String(m.horas));setValor(String(m.valor));};
  const pickColab=(id:string)=>{setColabId(id);const c=people.find(p=>p.id===id);const pt=c?activePattern(c):null;if(pt?.hora_entrada)setEntrada(pt.hora_entrada.slice(0,5));const wanted=pt?.tipo==="12x36"?12:8;applyMod(available.find(m=>Number(m.horas)===wanted)??available[0]);};
  const pickInicio=(v:string)=>{setInicio(v);if(!editing&&v)setFim(addCivilDays(v,29));};
  const reset=()=>{setEditing(null);setColabId("");setInicio(today);setFim(addCivilDays(today,29));setSubId("none");setModId("");setObs("");setFx(false);};
  const startEdit=(f:EscalaFerias)=>{setEditing(f.id);setColabId(f.colaborador_id);setInicio(f.inicio);setFim(f.fim);setSubId(f.substituto_id??"none");const m=available.find(x=>x.id===f.modalidade_id);setModId(m?.id??"");setHoras(String(f.horas_contratadas??m?.horas??8));setValor(String(f.valor_combinado??m?.valor??0));setEntrada(f.hora_entrada?.slice(0,5)??"08:00");setObs(f.observacao??"");;setFx(!!f.folgas_extra);if(f.folgas_extra){const fm=available.find(x=>x.id===f.folgas_modalidade_id);setFxModId(fm?.id??"");setFxHoras(String(f.folgas_horas??fm?.horas??8));setFxValor(String(f.folgas_valor??fm?.valor??150));setFxEntrada(f.folgas_hora_entrada?.slice(0,5)??"08:00");}};
  const plano=pattern&&inicio&&fim&&fim>=inicio?planejarFerias(pattern,inicio,fim,days.filter(d=>d.colaborador_id===colabId&&d.status!=="ferias")):null;
  const comCobertura=subId!=="none";
  const lista=(ferias.data??[]).filter(f=>f.unidade===unit);
  const submit=()=>{if(!colab||!pattern)return toast.error("Escolha quem vai sair de férias");if(!inicio||!fim||fim<inicio)return toast.error("Confira as datas");if(comCobertura&&!modalidade)return toast.error("Escolha a modalidade da freelancer");if(fx&&!fxMod)return toast.error("Escolha a modalidade do extra nas folgas");
    salvar.mutate({id:editing??undefined,colaborador:colab,pattern,unidade:unit,inicio,fim,substituto:comCobertura?frees.find(p=>p.id===subId)??null:null,modalidade:comCobertura?modalidade??null:null,hora_entrada:entrada,horas:Number(horas)||0,valor:Number(valor)||0,observacao:obs.trim()||null,folgasExtra:fx&&fxMod?{modalidade:fxMod,hora_entrada:fxEntrada,horas:Number(fxHoras)||0,valor:Number(fxValor)||0}:null},{onSuccess:r=>{toast.success(`Férias de ${colab.nome} lançadas`,{description:[`${r.diasFerias} dias de férias.`,comCobertura?`${nome(subId)} escalada em ${r.diasCobertura} dia(s).`:"Sem freelancer.",r.diasExtra?`${colab.nome} trabalha como extra em ${r.diasExtra} folga(s).`:"",r.coberturasFolgaRemovidas?`${r.coberturasFolgaRemovidas} plantão(ões) de folga da freelancer removido(s).`:"",r.ocupados.length?`Já tinha registro em ${r.ocupados.map(fmt).join(", ")}; esses dias ficaram como estavam.`:""].filter(Boolean).join(" ")});reset();},onError:e=>toast.error(e instanceof Error?e.message:"Não foi possível salvar")});};
  return <Dialog open onOpenChange={v=>!v&&onClose()}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>Férias · {unit}</DialogTitle><DialogDescription>Marque quem vai sair de férias. Os dias ficam como “Férias” na escala e a freelancer escolhida é escalada nos dias em que a pessoa trabalharia (vai para o Financeiro).</DialogDescription></DialogHeader>
    <div className="space-y-2">{ferias.isLoading?<p className="text-sm text-muted-foreground">Carregando…</p>:ferias.error?<p className="text-sm text-destructive">{ferias.error instanceof Error?ferias.error.message:"Erro ao carregar férias"}</p>:lista.length===0?<p className="rounded-md border border-dashed p-3 text-sm text-muted-foreground">Nenhuma férias lançada em {unit}.</p>:lista.map(f=>{const c=people.find(p=>p.id===f.colaborador_id);const ativa=f.inicio<=today&&f.fim>=today;return <div key={f.id} className={cn("flex flex-wrap items-center justify-between gap-2 rounded-md border p-3 text-sm",ativa&&"border-emerald-300 bg-emerald-50",editing===f.id&&"ring-2 ring-primary")}><div><p className="font-medium">{nome(f.colaborador_id)} {ativa&&<Badge className="ml-1 bg-emerald-600">Em férias</Badge>}{f.fim<today&&<Badge variant="outline" className="ml-1">Encerrada</Badge>}</p><p className="text-xs text-muted-foreground">{fmt(f.inicio)} a {fmt(f.fim)} · {f.substituto_id?`coberta por ${nome(f.substituto_id)}${f.valor_combinado!=null?` (${money(Number(f.valor_combinado))}/dia)`:""}`:"sem freelancer"}</p></div><div className="flex gap-2">{confirmDelete===f.id?<><Button size="sm" variant="destructive" disabled={excluir.isPending} onClick={()=>excluir.mutate({ferias:f,pattern:c?activePattern(c):null},{onSuccess:()=>{toast.success("Férias canceladas",{description:"Os dias voltaram ao padrão e a cobertura foi removida."});setConfirmDelete(null);if(editing===f.id)reset();},onError:e=>toast.error(e instanceof Error?e.message:"Não foi possível cancelar")})}>Confirmar</Button><Button size="sm" variant="outline" onClick={()=>setConfirmDelete(null)}>Voltar</Button></>:<><Button size="sm" variant="outline" onClick={()=>startEdit(f)}><Pencil className="mr-1 h-3 w-3"/>Editar</Button><Button size="sm" variant="outline" onClick={()=>setConfirmDelete(f.id)}>Cancelar férias</Button></>}</div></div>;})}</div>
    <Card className="space-y-4 p-4"><h3 className="font-semibold">{editing?"Editar férias":"Lançar férias"}</h3>
      <div className="grid gap-3 sm:grid-cols-3"><div className="space-y-2 sm:col-span-1"><Label>Quem sai de férias</Label><Select value={colabId} onValueChange={pickColab} disabled={!!editing}><SelectTrigger><SelectValue placeholder="Selecionar"/></SelectTrigger><SelectContent>{fixos.map(p=><SelectItem key={p.id} value={p.id}>{p.nome}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Início</Label><Input type="date" value={inicio} onChange={e=>pickInicio(e.target.value)}/></div><div className="space-y-2"><Label>Fim (último dia)</Label><Input type="date" value={fim} min={inicio} onChange={e=>setFim(e.target.value)}/></div></div>
      <div className="space-y-2"><Label>Freelancer que cobre</Label><Select value={subId} onValueChange={setSubId}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">Sem freelancer</SelectItem>{frees.map(p=><SelectItem key={p.id} value={p.id}>{p.nome}</SelectItem>)}</SelectContent></Select>{frees.length===0&&<p className="text-xs text-muted-foreground">Nenhuma freelancer ativa em {unit}. Cadastre em Equipe da Escala.</p>}</div>
      {comCobertura&&<><div className="grid gap-2">{available.map(m=><Button key={m.id} type="button" variant={modId===m.id?"default":"outline"} className="h-auto justify-start py-2 text-left" onClick={()=>applyMod(m)}>{m.nome} · {m.horas} h · {money(Number(m.valor))}</Button>)}</div>
      <div className="grid gap-3 sm:grid-cols-3"><div className="space-y-2"><Label>Entrada</Label><Input type="time" value={entrada} onChange={e=>setEntrada(e.target.value)}/></div><div className="space-y-2"><Label>Horas</Label><Input type="number" step="0.5" value={horas} onChange={e=>setHoras(e.target.value)}/></div><div className="space-y-2"><Label>Valor por dia</Label><Input type="number" step="0.01" value={valor} onChange={e=>setValor(e.target.value)}/></div></div></>}
      <div className="space-y-3 rounded-md border p-3"><label className="flex items-center gap-2 text-sm font-medium"><input type="checkbox" className="h-4 w-4" checked={fx} onChange={e=>{setFx(e.target.checked);if(e.target.checked&&!fxModId)applyFxMod(available.find(m=>m.motivo==="reforco_ocupacao")??available[0]);}}/>Nas folgas dela, {colab?.nome??"a pessoa"} trabalha como extra{comCobertura?` e ${nome(subId)} folga`:""}</label>
        {fx&&<><div className="grid gap-2">{available.map(m=><Button key={m.id} type="button" variant={fxModId===m.id?"default":"outline"} className="h-auto justify-start py-2 text-left" onClick={()=>applyFxMod(m)}>{m.nome} · {m.horas} h · {money(Number(m.valor))}</Button>)}</div>
        <div className="grid gap-3 sm:grid-cols-3"><div className="space-y-2"><Label>Entrada</Label><Input type="time" value={fxEntrada} onChange={e=>setFxEntrada(e.target.value)}/></div><div className="space-y-2"><Label>Horas</Label><Input type="number" step="0.5" value={fxHoras} onChange={e=>setFxHoras(e.target.value)}/></div><div className="space-y-2"><Label>Valor por dia</Label><Input type="number" step="0.01" value={fxValor} onChange={e=>setFxValor(e.target.value)}/></div></div></>}
      </div>
      <div className="space-y-2"><Label>Observação</Label><Textarea value={obs} onChange={e=>setObs(e.target.value)} placeholder="Opcional"/></div>
      {plano&&<div className="rounded-md border bg-muted/40 p-3 text-sm"><p><strong>{plano.diasFerias.length}</strong> dias de férias ({fmt(inicio)} a {fmt(fim)}).</p>{comCobertura?<p className="mt-1">{nome(subId)} cobre <strong>{plano.diasCobertura.length}</strong> dia(s) de trabalho · total {money(plano.diasCobertura.length*(Number(valor)||0))} · saída {calculateEndTime(entrada,Number(horas)||0)}</p>:<p className="mt-1 text-amber-700">{plano.diasCobertura.length} dia(s) de trabalho ficarão sem cobertura.</p>}{fx&&<p className="mt-1">{colab?.nome} trabalha como extra em <strong>{plano.diasFerias.length-plano.diasCobertura.length}</strong> folga(s) · total {money((plano.diasFerias.length-plano.diasCobertura.length)*(Number(fxValor)||0))}</p>}<p className="mt-1 text-xs text-muted-foreground">Dias em que a freelancer já tiver outro registro ficam como estão. Plantões de “Cobertura de folga” da freelancer para esta pessoa no período são removidos.</p></div>}
    </Card>
    <DialogFooter>{editing&&<Button variant="outline" onClick={reset}>Novo lançamento</Button>}<Button variant="outline" onClick={onClose}>Fechar</Button><Button disabled={!colabId||salvar.isPending} onClick={submit}>{salvar.isPending?"Salvando…":editing?"Salvar alterações":"Lançar férias"}</Button></DialogFooter>
  </DialogContent></Dialog>;
}

function ToggleValores(){const [v,set]=useMostrarValores();return <Button variant="outline" onClick={()=>set(!v)} title={v?"Esconder os valores pagos aos freelancers":"Mostrar os valores pagos aos freelancers"}>{v?<EyeOff className="mr-2 h-4 w-4"/>:<Eye className="mr-2 h-4 w-4"/>}{v?"Esconder valores":"Mostrar valores"}</Button>}
